    91  bool vcardtime_is_leap_year(const int year)
    92  {
    93      if (year == -1) {
    94          return true;
    95      } else if (year <= 1752) {
    96          return (year % 4 == 0);
    97      } else {
    98          return ((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0);
    99      }
