   102  static const int days_in_month[] =
   103      {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
   104
   105  bool vcardtime_is_valid_time(const struct vcardtimetype t)
   106  {
   107      int days;
   108
   109      if (t.year > 3000 || t.day == 0 ||
   110          t.hour > 23 || t.minute > 59 || t.second > 60 ||
   111          t.utcoffset < -720 || t.utcoffset > 840) {
   112          return false;
   113      }
   114
   115      if (t.minute == -1 && t.hour != -1 && t.second != -1) {
   116          return false;
   117      }
   118
   119      switch (t.month) {
   120      case 0:
   121          return false;
   122
   123      case -1:
   124          if (t.year != -1 && t.day != -1) {
   125              return false;
   126          }
   127
   128          days = 31;
   129          break;
   130
   131      case 2:
   132          days = 28 + vcardtime_is_leap_year(t.year);
   133          break;
   134
   135      default:
   136          if (t.month > 12) {
   137              return false;
   138          }
   139
   140          days = days_in_month[t.month];
   141          break;
   142      }
   143
   144      if (t.day > days) {
   145          return false;
   146      }
   147
   148      return true;
   149  }
